import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { ratesQuery } from '../rates/ratesQuery';
import { useFloor, useLate } from '../settings/settingsQuery';
import { useUser } from '../session/useUser';
import { periodDue, periodOf, periodsKey, periodsQuery, personPeriodDue } from './periodsQuery';
import type { Period } from './periodsQuery';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

function ClaimPeriod({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  return <td data-testid="claim-period">{periodOf(periods, claim.date)?.name ?? ''}</td>;
}

/** A column per period on the sheet, headed by its name. */
function PersonPeriodHeaders({ sheetId }: { sheetId: string }) {
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  return (
    <>
      {periods.map((p) => (
        <th key={p.name}>{p.name}</th>
      ))}
    </>
  );
}

/** The person's due-total for each period on the sheet: live while it is open, fixed while it is closed. */
function PersonPeriodDues({ sheetId, personId }: { sheetId: string; personId: number }) {
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const person = people.find((p) => p.id === personId);
  if (!person) return null;
  return (
    <>
      {periods.map((p) => (
        <td key={p.name} data-testid={`person-period-${p.name}-due-total`}>
          {personPeriodDue(p, person, claims, people, rates, floor, late)}
        </td>
      ))}
    </>
  );
}

/** A period's closed flag and the buttons that close and reopen it (each for the roles the settings' permission matrix allows: by default closing is a clerk's or a steward's, reopening a steward's). A refusal
 *  shows on the period until its next action. */
function PeriodClosed({ sheetId, period }: { sheetId: string; period: Period }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [error, setError] = useState('');
  const once = useSubmitOnce();
  const close = useMutation({
    mutationFn: () =>
      putJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(period.name)}/close`,
        {},
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
    onError: () => setError(`The period ${period.name} could not be closed: it is already closed, or your role is not allowed to close it.`),
  });
  const reopen = useMutation({
    mutationFn: () =>
      putJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(period.name)}/reopen`,
        {},
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
    onError: () =>
      setError(`The period ${period.name} could not be reopened: it is not closed, or your role is not allowed to reopen it.`),
  });

  return (
    <td>
      <span data-testid="period-closed">{period.closed ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="period-close"
        disabled={close.isPending}
        onClick={() => {
          setError('');
          once(() => close.mutateAsync());
        }}
      >
        Close
      </button>{' '}
      <button
        type="button"
        data-testid="period-reopen"
        disabled={reopen.isPending}
        onClick={() => {
          setError('');
          once(() => reopen.mutateAsync());
        }}
      >
        Reopen
      </button>
      {error && <span data-testid="period-error">{error}</span>}
    </td>
  );
}

/** The sheet's periods, each with its due-total — the figures of the counting claims dated in it, fixed
 *  while the period is closed and live again once it is reopened — and the form a period is added through. */
function Periods({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const periods = useQuery(periodsQuery(sheetId));
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: Pick<Period, 'name' | 'from' | 'to'>) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
      setName('');
      setFrom('');
      setTo('');
    },
    onError: () => setError('The period could not be added: its name must be new and its dates must not overlap another period.'),
  });

  const list = periods.data ?? [];
  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const n = name.trim();
    const f = from.trim();
    const t = to.trim();
    if (n === '') {
      setError('A period needs a name.');
      return;
    }
    if (!DATE.test(f) || !DATE.test(t)) {
      setError('The from and to dates must be dates (yyyy-mm-dd).');
      return;
    }
    if (t < f) {
      setError('The to-date must be on or after the from-date.');
      return;
    }
    if (list.some((p) => p.name === n)) {
      setError(`There is already a period named ${n}.`);
      return;
    }
    const overlapped = list.find((p) => p.from <= t && f <= p.to);
    if (overlapped) {
      setError(`The period overlaps ${overlapped.name}.`);
      return;
    }
    once(() => add.mutateAsync({ name: n, from: f, to: t }));
  };

  const dueTotal = (period: Period) => periodDue(period, claims, people, rates, floor, late);

  const edit = (set: (v: string) => void) => (e: { target: { value: string } }) => {
    set(e.target.value);
    setError('');
  };

  return (
    <section data-testid="periods">
      <h3>Periods</h3>
      <form data-testid="period-form" onSubmit={submit}>
        <label>
          Name <input data-testid="period-form-name" value={name} onChange={edit(setName)} />
        </label>{' '}
        <label>
          From <input data-testid="period-form-from" type="date" value={from} onChange={edit(setFrom)} />
        </label>{' '}
        <label>
          To <input data-testid="period-form-to" type="date" value={to} onChange={edit(setTo)} />
        </label>{' '}
        <button type="submit" data-testid="period-form-submit" disabled={add.isPending}>
          Add period
        </button>
        {error && <p data-testid="period-form-error">{error}</p>}
      </form>
      {periods.isError && <p data-testid="periods-load-error">Could not load the periods.</p>}
      <table data-testid="periods-list">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
          </tr>
        </thead>
        <tbody>
          {list.map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{dueTotal(p)}</td>
              <PeriodClosed sheetId={sheetId} period={p} />
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

// Keyed by sheet, so a typed period or an error never carries over to another sheet.
export const contributions = [
  ClaimCells.fill({ order: 15, Component: ClaimPeriod }),
  PersonHeaders.fill({ order: 15.5, Component: PersonPeriodHeaders }),
  PersonCells.fill({ order: 15.5, Component: PersonPeriodDues }),
  SheetPanel.fill({ order: 7, Component: ({ sheetId }) => <Periods key={sheetId} sheetId={sheetId} /> }),
];
import { getJson } from '../../api/http';
import { counts, isOpen } from '../claims/claimsQuery';
import type { Claim, ClaimStatus } from '../claims/claimsQuery';
import type { Person } from '../people/peopleQuery';
import { figure, sumDue } from '../rates/ratesQuery';
import type { Late, Rate } from '../rates/ratesQuery';
import { sheetKey } from '../sheet/sheetQuery';
import type { DatedValue } from '../settings/dated';

/**
 * A sheet's period: a name unique on the sheet, `from` and `to` (yyyy-mm-dd) inclusive. Periods never overlap.
 * A closed period's due-total was fixed when it was closed (`closedTotal`; null while open), and so was each
 * person's due-total for it (`personTotals`, by person id; empty while open, and a person added later has none).
 */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  personTotals: Record<string, string>;
};

/** Under the sheet's key, so re-loading the sheet re-reads its periods. */
export const periodsKey = (sheetId: string) => [...sheetKey(sheetId), 'periods'] as const;

/** The sheet's periods, by from-date. */
export const periodsQuery = (sheetId: string) => ({
  queryKey: periodsKey(sheetId),
  queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`),
});

/** The period whose dates contain the date (yyyy-mm-dd), or undefined when none does. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/**
 * The claim's status at the end of the day `on` (yyyy-mm-dd), as its log records it: the last status logged on or
 * before it, DRAFT (counting nowhere) when it was added after. A claim with no log has its status now.
 */
export function statusOn(c: Claim, on: string): ClaimStatus {
  const log = c.log ?? [];
  if (log.length === 0) return c.status;
  let status: ClaimStatus = 'DRAFT';
  for (const line of log) {
    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=\S*$/.exec(line);
    if (m && m[2] <= on) status = m[1] as ClaimStatus;
  }
  return status;
}

/**
 * A person's due-total for a period: the figures (as shown now) of their claims dated in it that counted by the
 * status they had at the end of its last day. A hold leaves out only a claim that is open now. While the period is
 * closed it is the figure fixed when it was closed (0.00 for a person added since).
 */
export function personPeriodDue(
  period: Period,
  person: Person,
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  floor: DatedValue[],
  late: Late,
): string {
  if (period.closed) return period.personTotals[String(person.id)] ?? '0.00';
  return sumDue(
    claims
      .filter(
        (c) =>
          c.personId === person.id &&
          period.from <= c.date &&
          c.date <= period.to &&
          counts({ ...c, status: statusOn(c, period.to) }, isOpen(c) ? people : [], late.today),
      )
      .map((c) => figure(c, rates, person, floor, late)),
  );
}

/** A period's due-total: its people's due-totals for it added up. */
export function periodDue(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: DatedValue[], late: Late): string {
  return sumDue(people.map((p) => personPeriodDue(period, p, claims, people, rates, floor, late)));
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from '../people/peopleQuery';
import { claimsKey, claimsQuery } from './claimsQuery';
import type { Claim } from './claimsQuery';
import { useSelectedClaims } from './useSelectedClaims';

type Result = { opened: number; refused: number };

/**
 * Opens every ticked claim, one at a time in list order (people in their list order, newest claim
 * first within a person), so each is numbered in that order. A claim the server refuses to open is
 * left as it is and counted as refused.
 */
function BulkOpen({ user, sheetId }: { user: string; sheetId: string }) {
  const queryClient = useQueryClient();
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const [selected, setSelected] = useSelectedClaims();
  const [result, setResult] = useState<Result | undefined>();
  const once = useSubmitOnce();

  const ordered = people.flatMap((p) => claims.filter((c) => c.personId === p.id && selected.includes(c.id)));

  const open = useMutation({
    mutationFn: async (targets: Claim[]): Promise<Result> => {
      let opened = 0;
      for (const c of targets) {
        try {
          await putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/status/OPEN`, {}, user);
          opened++;
        } catch {
          // refused: left as it is
        }
      }
      return { opened, refused: targets.length - opened };
    },
    onSuccess: async (r) => {
      setSelected([]);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      setResult(r);
    },
  });

  return (
    <section data-testid="bulk-open-panel">
      <button
        type="button"
        data-testid="bulk-open"
        disabled={open.isPending}
        onClick={() => {
          setResult(undefined);
          once(() => open.mutateAsync(ordered));
        }}
      >
        Open selected
      </button>
      {result && (
        <>
          {' '}
          Opened <span data-testid="bulk-opened">{result.opened}</span>, refused{' '}
          <span data-testid="bulk-refused">{result.refused}</span>
        </>
      )}
    </section>
  );
}

export const contribution = SheetPanel.fill({
  order: 21,
  Component: ({ user, sheetId }) => <BulkOpen key={sheetId} user={user} sheetId={sheetId} />,
});
